// Per-ship jump signatures: rendering only; never modify flight physics.
const shipJumpTraits=[['안정 점프','기체 자세를 유지하는 기본 점프'],['레프트 롤','왼쪽으로 한 바퀴 회전'],['트윈 서지','쌍발 추진 에너지를 펼치는 점프'],['프런트 플립','앞으로 한 바퀴 공중제비'],['헤비 리프트','하강 추진광을 분사하는 묵직한 상승'],['라이트 롤','오른쪽으로 한 바퀴 회전'],['백 플립','뒤로 한 바퀴 공중제비'],['해머 뱅크','좌우로 기울였다가 복귀'],['코르크스크루','기울임과 회전을 결합한 곡예 점프'],['오비탈 스핀','원반 기체가 수평으로 한 바퀴 회전'],['윙 웨이브','날개를 흔들듯 기울이며 상승'],['자이로 점프','비대칭 동체를 균형 잡으며 회전']];
let shipTrickStart=null,shipTrickDuration=.6;
function liveShipTrick(){return shipTrickStart!==null&&!grounded&&state==='play'?Math.max(0,Math.min(1,(time-shipTrickStart)/shipTrickDuration)):null}
const trickJump=jump;jump=function(...args){const wasGrounded=grounded,out=trickJump(...args);if(wasGrounded&&!grounded&&vy>0&&state==='play'){shipTrickStart=time;shipTrickDuration=Math.max(.18,Math.min(.65,2*vy/(gravityValue()*.18)*.7))}return out};
const trickBegin=beginRun;beginRun=function(...args){shipTrickStart=null;return trickBegin(...args)};
const trickStep=step;step=function(...args){const out=trickStep(...args);if(grounded||!['play','pause'].includes(state))shipTrickStart=null;return out};
function trickTransform(id,phase){const u=Math.max(0,Math.min(1,phase)),smooth=u*u*(3-2*u),turn=smooth*Math.PI*2,pulse=Math.sin(Math.PI*u);let roll=0,flip=0,yaw=0;if(id===1)roll=-turn;if(id===5)roll=turn;if(id===3)flip=turn;if(id===6)flip=-turn;if(id===7)roll=Math.sin(turn)*.65;if(id===8){roll=turn;flip=Math.sin(Math.PI*u)*.8}if(id===9)yaw=turn;if(id===10)roll=Math.sin(turn*2)*.45*pulse;if(id===11){roll=Math.sin(turn)*.55;flip=Math.sin(turn)*.35}return {roll,flip,yaw,pulse}}
const trickRender=renderFlightShip;renderFlightShip=function(g,id,t,size,pose){const phase=pose.jumpTrick;let {roll,flip,yaw,pulse}=Number.isFinite(phase)?trickTransform(id,phase):{roll:0,flip:0,yaw:0,pulse:0};flip+=pose.landingPitch||0;const q=size/50;g.save();try{g.translate(0,(pose.landingSink||0)*q);if(id===2||id===4){g.save();g.globalAlpha*=pulse*.65;g.strokeStyle=id===2?'#b7a1ff':'#91eddb';g.lineWidth=2*q;for(const side of [-1,1]){g.beginPath();g.moveTo(side*18*q,10*q);g.lineTo(side*(id===2?34:20)*q,(24+pulse*25)*q);g.stroke()}g.restore()}return renderSolidJumpShip(g,id,t,size,pose,{roll,flip,yaw});}finally{g.restore()}};
// Animate the selected ship without requiring input or changing the equipped loadout.
function paintTrickShopPreview(previewTime=performance.now()/1000){if(menuScreen!=='shop'||cosmeticTab==='coins')return;if(cosmeticTab==='trail'){previewCosmetic($('shopPreview'),true,previewTime);return}const canvas=$('shopPreview'),g=canvas.getContext('2d'),id=cosmeticTab==='ship'?shopSelection:data.skin,cycle=previewTime%2.8,u=cycle<.55?0:cycle<1.75?(cycle-.55)/1.2:1,air=cycle>=.55&&cycle<1.75,old=cosmeticPreview;cosmeticPreview=cosmeticTab==='ship'?null:{[cosmeticTab]:cosmeticSelection};try{g.clearRect(0,0,canvas.width,canvas.height);g.save();g.translate(canvas.width/2,canvas.height*.46-Math.sin(Math.PI*u)*canvas.height*.14);const landing=globalThis.starwayShipLandingReady&&cycle>=1.75?landingPoseAt((cycle-1.75)/.3,.85):{sink:0,pitch:0,boost:0};renderFlightShip(g,id,cycle,96,{foreshortening:.72,shear:0,thrust:(air?.65:.2)+landing.boost,jumpTrick:air?u:null,landingSink:landing.sink,landingPitch:landing.pitch});g.restore()}finally{cosmeticPreview=old}}
const trickShop=renderShopInterface;renderShopInterface=function(...args){const out=trickShop(...args);if(cosmeticTab==='ship'){$('shopJumpTrait').textContent='고유 점프 · '+shipJumpTraits[shopSelection][0];$('shopJumpTrait').title=shipJumpTraits[shopSelection][1]}else $('shopJumpTrait').textContent='';paintTrickShopPreview();return out};
globalThis.starwayShipTricksReady=true;
